def main():
    sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'scripts'))
    import course_weak as c
    from compile_course_ai import compile_decisions
    from prepare_course_weak import verify_dataset
    root = Path(__file__).resolve().parents[2]
    dataset = root / 'kg_datasets/dblp/course_v4_weak'
    output = root / 'kg_datasets/dblp/course_v4_runs/test_ner_authored_20261006_09'
    if output.exists():
        raise FileExistsError('Preserve authored semantic export')
    paths = [dataset / 'jobs/generation' / f'batch-{i:04d}.jsonl' for i in range(73,81)]
    hashes = {str(p.resolve()): c.file_sha256(p) for p in [Path(__file__), *paths]}
    jobs = [r for p in paths for r in c.read_jsonl(p)]
    references = {r['sampleId']: r for r in verify_dataset(dataset)}
    assert len(GENERATION) == len(jobs) == 200
    assert {r[0] for r in GENERATION} == {r['sampleId'] for r in jobs}
    assert all(references[r['sampleId']]['split']=='test' and r==c.model_payload(references[r['sampleId']]) for r in jobs)
    decisions = []
    for row in GENERATION:
        assert len(row) in (4,5) and row[1] in ('complete','unresolved') and row[3].strip()
        decisions.append({'sampleId': row[0], 'entityStatus': row[1], 'entityReason': row[3] if row[1]=='unresolved' else '',
                          'entities': [{'text': item[0], 'label': item[1], **({'occurrence':item[2]} if len(item)==3 else {})} for item in row[2]],
                          'groupMentions': [{'text': text, 'label': 'METHOD'} for text in row[4]] if len(row)==5 else [],
                          'relationStatus':'unresolved', 'relationReason':'Relation extraction not performed in this explicitly NER-only pass; no complete relation labels or negatives inferred.',
                          'relations':[], 'notes': row[3]})
        # Explicit NER-only policy: enumerate pending pairs as UNRESOLVED, never infer a semantic relation or negative.
        entities = [{'entityId': f'e{i}', 'label': e['label']} for i,e in enumerate(decisions[-1]['entities'],1)]
        decisions[-1]['relations'] = [{'head':head,'tail':tail,'label':'UNRESOLVED',
                                      'reason':decisions[-1]['relationReason']} for head,tail in c.candidate_pairs(entities)]
    compile_decisions(decisions,[references[j['sampleId']] for j in jobs])
    assert all(c.file_sha256(Path(p))==h for p,h in hashes.items())
    output.mkdir(parents=True,exist_ok=False)
    shutil.copyfile(Path(__file__), output / 'authored_generation.py')
    c.write_json(output/'generation_decisions.json',{'provider':'codex_session','model':'unknown_session_model','round':'generation','decisions':decisions})
    c.write_jsonl(output/'jobs.jsonl',jobs)
    c.write_json(output/'manifest.json',{'inputSha256':hashes,'taskScope':'NER_only','modelCallExecutedByExporter':False,
                 'filesSha256':{p.name:c.file_sha256(p) for p in output.iterdir() if p.is_file()}})
    print({'documents':len(decisions),'output':str(output)})


if __name__=='__main__':
    main()
